package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_binomialCoefficient_TriageGen0Test {

    @Test
    public void testBinomialCoefficient_Success() {
        // Basic cases
        assertEquals(1L, MathUtils.binomialCoefficient(5, 0));
        assertEquals(1L, MathUtils.binomialCoefficient(5, 5));
        assertEquals(5L, MathUtils.binomialCoefficient(5, 1));
        assertEquals(5L, MathUtils.binomialCoefficient(5, 4));
        assertEquals(10L, MathUtils.binomialCoefficient(5, 2));
        assertEquals(10L, MathUtils.binomialCoefficient(5, 3));

        // Larger values
        assertEquals(252L, MathUtils.binomialCoefficient(10, 5));
        assertEquals(4862L, MathUtils.binomialCoefficient(16, 8));

        // Boundary for n <= 61 (where naive implementation works)
        // 61 choose 30 is a large number but fits in long
        assertEquals(2327141768782744320L, MathUtils.binomialCoefficient(61, 30));
    }










}

