import static org.junit.Assert.assertEquals;

public class MathUtils_binomialCoefficient_TriageGen0Test {









    @Test
    public void testBinomialCoefficient_EdgeCases() {
        // n=0, k=0 -> should return 1
        assertEquals(1L, MathUtils.binomialCoefficient(0, 0));

        // n=1, k=0 -> 1
        assertEquals(1L, MathUtils.binomialCoefficient(1, 0));

        // n=1, k=1 -> 1
        assertEquals(1L, MathUtils.binomialCoefficient(1, 1));
    }


}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_binomialCoefficient_TriageGen0Test {











    /**
     * This test targets the specific logic path involving binomialCoefficientDouble.
     * Note: Since we cannot easily mock the static method binomialCoefficientDouble 
     * without PowerMock, we rely on standard inputs that force the execution 
     * of the result calculation path.
     */
    @Test
    public void testBinomialCoefficient_CalculationPath() {
        // This bypasses the (n==k), (k==0), (k==1), (k==n-1) shortcuts
        // and goes into the Math.round(binomialCoefficientDouble(n, k)) path.
        assertEquals(35L, MathUtils.binomialCoefficient(7, 3));
        assertEquals(35L, MathUtils.binomialCoefficient(7, 4));
    }
}
